return [{ json: {
  "take": "puppy-treat-demo",
  "brief": "A puppy and its treat on a cream rug. Keep shoes out of the shot.",
  "historyComplete": false,
  "previousAttempts": [],
  "requirements": [
    {
      "id": "subject",
      "description": "The puppy and treat are visible.",
      "observation": {
        "status": "pass",
        "fromSeconds": 0.5,
        "detail": "The puppy and treat are both visible."
      }
    },
    {
      "id": "footwear",
      "description": "No shoe is visible.",
      "observation": {
        "status": "fail",
        "fromSeconds": 0.5,
        "toSeconds": 3,
        "detail": "A torn sneaker is visible in the lower-right corner at 0.5, 2, and 3 seconds."
      },
      "edit": {
        "action": "Mask the sneaker and patch the corner, then preview the edit.",
        "availableAsset": "Existing shot with adjacent rug and floor texture.",
        "reason": "The shoe is separate from the puppy and treat in the sampled frames."
      }
    }
  ]
} }];

return $input.all().map(({json}) => {
  const { take, brief, historyComplete = false, previousAttempts = [], requirements } = json;
  if (typeof take !== 'string' || typeof brief !== 'string' || !Array.isArray(requirements) || !requirements.length) {
    throw new Error('Provide take, brief and at least one requirement with reviewer observations.');
  }
  return { json: { jsonrpc: '2.0', id: 1, method: 'tools/call', params: {
    name: 'decide_render_retry',
    arguments: { take, brief, historyComplete, previousAttempts, requirements }
  } } };
});

return $input.all().map(({json}) => {
  const result = json.result;
  if (json.error || result?.isError || !result?.structuredContent?.decision) {
    const detail = json.error?.message ?? result?.content?.find(item => item.type === 'text')?.text;
    throw new Error(detail ?? 'Render Check did not return a decision.');
  }
  return { json: { ...result.structuredContent, spendApproved: false } };
});
